/**
 * Corporate Radio Station API — Layer 2 (on-demand feed).
 *
 * Mounted at /api/radio by server.js. All routes require the normal JWT
 * (authenticateToken). Segments are pre-generated by server/cron/radioWorker.js;
 * this router only assembles a per-listener feed, applying the SAME visibility
 * predicate the forum uses, so a user hears exactly what they could read.
 */
const express = require('express');
const { visiblePostsWhere, canUserViewPost } = require('../lib/postVisibility');
const { summarizePostForRadio, contentHash, loadComments, estimateSeconds } = require('../lib/radioSummarizer');

module.exports = function createRadioRouter({ db, authenticateToken, requireAdmin }) {
  const router = express.Router();
  router.use(authenticateToken);

  const companyName = () => process.env.COMPANY_SHORT_NAME || process.env.COMPANY_NAME || 'Intranet';

  function clampInt(v, def, min, max) {
    const n = parseInt(v, 10);
    if (Number.isNaN(n)) return def;
    return Math.min(max, Math.max(min, n));
  }

  function buildIntro({ userName, unheard, total, sinceDays }) {
    const hour = new Date().getHours();
    const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';
    const first = (userName || '').split(' ')[0];
    const who = first ? `, ${first}` : '';
    let count;
    if (unheard === 0 && total === 0) count = `There are no new stories from the last ${sinceDays} days. Check back later.`;
    else if (unheard === 0) count = `You are all caught up. Here are your ${total === 1 ? 'latest story' : `${total} latest stories`} again.`;
    else count = `You have ${unheard === 1 ? 'one new story' : `${unheard} new stories`}.`;
    return `${greeting}${who}. This is ${companyName()} Radio. ${count}`;
  }

  /**
   * GET /api/radio/feed
   *   ?days=7        look-back window (1..90)
   *   ?limit=30      max segments (1..100)
   *   ?unheard=1     exclude segments this user already completed
   *   ?since=ISO     only posts created after this timestamp (overrides days)
   */
  router.get('/feed', async (req, res) => {
    try {
      const userId = req.user.userId;
      const days = clampInt(req.query.days, 7, 1, 90);
      const limit = clampInt(req.query.limit, 30, 1, 100);
      const unheardOnly = req.query.unheard === '1' || req.query.unheard === 'true';
      const since = req.query.since && !Number.isNaN(Date.parse(req.query.since))
        ? new Date(req.query.since)
        : new Date(Date.now() - days * 86400000);

      const vis = visiblePostsWhere('p', userId);
      const params = [userId, ...vis.params, since];
      let where = `s.status = 'ready' AND ${vis.sql} AND p.created_at >= ?`;
      if (unheardOnly) where += ' AND rl.id IS NULL';

      const [rows] = await db.query(
        `SELECT s.id AS segment_id, s.headline, s.tts_text, s.word_count, s.est_duration_secs,
                s.generated_at, s.model,
                p.id AS post_id, p.title, p.slug, p.created_at AS posted_at, p.is_pinned,
                u.id AS author_id, u.name AS author_name, u.avatar_url AS author_avatar,
                (rl.id IS NOT NULL) AS heard, rl.listened_at,
                (SELECT COUNT(*) FROM comments c WHERE c.post_id = p.id) AS comment_count,
                (SELECT GROUP_CONCAT(t.name ORDER BY t.name SEPARATOR ',')
                   FROM post_tags pt JOIN tags t ON t.id = pt.tag_id WHERE pt.post_id = p.id) AS tags
         FROM radio_segments s
         JOIN posts p ON p.id = s.post_id
         JOIN users u ON u.id = p.user_id
         LEFT JOIN radio_listens rl ON rl.segment_id = s.id AND rl.user_id = ?
         WHERE ${where}
         ORDER BY p.is_pinned DESC, p.created_at DESC
         LIMIT ${limit}`,
        params
      );

      const segments = rows.map(r => ({
        segment_id: r.segment_id,
        post_id: r.post_id,
        slug: r.slug,
        headline: r.headline,
        title: r.title,
        tts_text: r.tts_text,
        word_count: r.word_count,
        est_duration_secs: r.est_duration_secs,
        author: { id: r.author_id, name: r.author_name, avatar_url: r.author_avatar },
        tags: r.tags ? r.tags.split(',') : [],
        comment_count: r.comment_count,
        is_pinned: !!r.is_pinned,
        posted_at: r.posted_at,
        generated_at: r.generated_at,
        heard: !!r.heard,
        listened_at: r.listened_at
      }));

      const unheard = segments.filter(s => !s.heard).length;
      const totalSecs = segments.reduce((a, s) => a + (s.est_duration_secs || 0), 0);

      const [[me]] = await db.execute('SELECT name FROM users WHERE id = ?', [userId]);

      res.json({
        station: {
          name: `${companyName()} Radio`,
          intro_text: buildIntro({ userName: me?.name, unheard, total: segments.length, sinceDays: days }),
          outro_text: `That is all for now from ${companyName()} Radio. Open the intranet app to reply or read the full posts.`,
          generated_at: new Date().toISOString(),
          since: since.toISOString(),
          total: segments.length,
          unheard,
          est_total_secs: totalSecs
        },
        segments
      });
    } catch (error) {
      console.error('[radio] feed error:', error);
      res.status(500).json({ error: 'Failed to build radio feed' });
    }
  });

  /** GET /api/radio/segments/:id — a single segment (permission checked). */
  router.get('/segments/:id', async (req, res) => {
    try {
      const [[row]] = await db.execute(
        `SELECT s.*, p.user_id, p.visibility, p.slug, p.title FROM radio_segments s
         JOIN posts p ON p.id = s.post_id WHERE s.id = ?`, [req.params.id]);
      if (!row) return res.status(404).json({ error: 'Segment not found' });
      const ok = await canUserViewPost(db, { id: row.post_id, user_id: row.user_id, visibility: row.visibility }, req.user.userId);
      if (!ok) return res.status(403).json({ error: 'Not allowed' });
      res.json(row);
    } catch (error) {
      console.error('[radio] segment error:', error);
      res.status(500).json({ error: 'Failed to load segment' });
    }
  });

  /**
   * GET /api/radio/posts/by-slug/:slug — the radio segment for a post, for the
   * web page /forum/post/:slug/tts. 404 with {pending:true} when the worker has
   * not produced one yet. Permission = the post's own visibility.
   */
  router.get('/posts/by-slug/:slug', async (req, res) => {
    try {
      const [[post]] = await db.execute(
        `SELECT p.id, p.user_id, p.visibility, p.slug, p.title, p.created_at, p.updated_at,
                u.name AS author_name, u.avatar_url AS author_avatar, u.intranet_username AS author_username
         FROM posts p JOIN users u ON u.id = p.user_id WHERE p.slug = ? LIMIT 1`, [req.params.slug]);
      if (!post) return res.status(404).json({ error: 'Post not found' });
      const ok = await canUserViewPost(db, post, req.user.userId);
      if (!ok) return res.status(403).json({ error: 'Not allowed' });
      const [[seg]] = await db.execute(
        `SELECT s.id AS segment_id, s.headline, s.tts_text, s.word_count, s.est_duration_secs, s.model, s.status, s.error,
                s.is_manual, s.edited_by, eu.name AS edited_by_name, s.comment_count,
                (SELECT COUNT(*) FROM comments c WHERE c.post_id = s.post_id) AS current_comment_count,
                s.generated_at, s.updated_at, (rl.id IS NOT NULL) AS heard, rl.listened_at
         FROM radio_segments s LEFT JOIN radio_listens rl ON rl.segment_id = s.id AND rl.user_id = ?
         LEFT JOIN users eu ON eu.id = s.edited_by
         WHERE s.post_id = ?`, [req.user.userId, post.id]);
      const postInfo = { id: post.id, slug: post.slug, title: post.title, created_at: post.created_at, updated_at: post.updated_at,
        author: { id: post.user_id, name: post.author_name, avatar_url: post.author_avatar, username: post.author_username },
        can_regenerate: req.user.role === 'admin' || post.user_id === req.user.userId };
      if (!seg) return res.status(404).json({ pending: true, post: postInfo, station: `${companyName()} Radio`, error: 'No radio segment yet' });
      res.json({ post: postInfo, station: `${companyName()} Radio`, segment: { ...seg, heard: !!seg.heard, is_manual: !!seg.is_manual } });
    } catch (error) {
      console.error('[radio] by-slug error:', error);
      res.status(500).json({ error: 'Failed to load radio segment' });
    }
  });

  /**
   * POST /api/radio/segments/:id/listened  { completed?: boolean }
   * Marks a segment as heard for the current user (idempotent).
   */
  router.post('/segments/:id/listened', async (req, res) => {
    try {
      const segmentId = parseInt(req.params.id, 10);
      if (Number.isNaN(segmentId)) return res.status(400).json({ error: 'Invalid segment id' });
      const completed = req.body?.completed === false ? 0 : 1;
      const [[seg]] = await db.execute(
        'SELECT s.post_id, p.user_id, p.visibility FROM radio_segments s JOIN posts p ON p.id = s.post_id WHERE s.id = ?',
        [segmentId]);
      if (!seg) return res.status(404).json({ error: 'Segment not found' });
      const ok = await canUserViewPost(db, { id: seg.post_id, user_id: seg.user_id, visibility: seg.visibility }, req.user.userId);
      if (!ok) return res.status(403).json({ error: 'Not allowed' });
      await db.execute(
        `INSERT INTO radio_listens (user_id, segment_id, completed) VALUES (?, ?, ?)
         ON DUPLICATE KEY UPDATE completed = GREATEST(completed, VALUES(completed)), listened_at = CURRENT_TIMESTAMP`,
        [req.user.userId, segmentId, completed]);
      res.json({ ok: true, segment_id: segmentId, completed: !!completed });
    } catch (error) {
      console.error('[radio] listened error:', error);
      res.status(500).json({ error: 'Failed to record listen' });
    }
  });

  /** POST /api/radio/listens/reset — forget listening history (start over). */
  router.post('/listens/reset', async (req, res) => {
    try {
      const [r] = await db.execute('DELETE FROM radio_listens WHERE user_id = ?', [req.user.userId]);
      res.json({ ok: true, removed: r.affectedRows });
    } catch (error) {
      res.status(500).json({ error: 'Failed to reset history' });
    }
  });

  /** GET /api/radio/status — worker health (counts visible to this user + global generation stats). */
  router.get('/status', async (req, res) => {
    try {
      const vis = visiblePostsWhere('p', req.user.userId);
      const [[g]] = await db.query(
        `SELECT
           (SELECT COUNT(*) FROM radio_segments WHERE status = 'ready') AS ready,
           (SELECT COUNT(*) FROM radio_segments WHERE status = 'failed') AS failed,
           (SELECT COUNT(*) FROM posts p LEFT JOIN radio_segments s ON s.post_id = p.id WHERE s.id IS NULL) AS pending_posts,
           (SELECT MAX(generated_at) FROM radio_segments) AS last_generated_at`);
      const [[mine]] = await db.query(
        `SELECT COUNT(*) AS visible_segments,
                SUM(rl.id IS NULL) AS unheard
         FROM radio_segments s JOIN posts p ON p.id = s.post_id
         LEFT JOIN radio_listens rl ON rl.segment_id = s.id AND rl.user_id = ?
         WHERE s.status = 'ready' AND ${vis.sql}`, [req.user.userId, ...vis.params]);
      res.json({
        station: `${companyName()} Radio`,
        worker: { ...g, model: process.env.RADIO_MODEL || require('../lib/radioSummarizer').DEFAULT_MODEL },
        me: { visible_segments: mine.visible_segments || 0, unheard: Number(mine.unheard) || 0 }
      });
    } catch (error) {
      console.error('[radio] status error:', error);
      res.status(500).json({ error: 'Failed to load status' });
    }
  });

  /**
   * PUT /api/radio/posts/:postId/segment  { headline, tts_text } — admin or post author.
   * Saves a hand-written segment and marks it manual so the worker leaves it alone
   * (Regenerate clears the flag). Word count / duration are recomputed here.
   */
  router.put('/posts/:postId/segment', async (req, res) => {
    try {
      const postId = parseInt(req.params.postId, 10);
      const [[post]] = await db.execute('SELECT id, user_id, title, content FROM posts WHERE id = ?', [postId]);
      if (!post) return res.status(404).json({ error: 'Post not found' });
      if (req.user.role !== 'admin' && post.user_id !== req.user.userId) return res.status(403).json({ error: 'Admin or author only' });
      const headline = String(req.body?.headline ?? post.title).replace(/\s+/g, ' ').trim().slice(0, 255);
      const tts = String(req.body?.tts_text ?? '').replace(/\r\n/g, '\n').replace(/[ \t]+/g, ' ').trim();
      if (tts.length < 20) return res.status(400).json({ error: 'Spoken text must be at least 20 characters' });
      if (tts.length > 5000) return res.status(400).json({ error: 'Spoken text must be under 5000 characters (about 5 minutes)' });
      const wordCount = (tts.match(/\S+/g) || []).length;
      const comments = await loadComments(db, postId);
      await db.execute(
        `INSERT INTO radio_segments (post_id, headline, tts_text, source_hash, comment_count, model, word_count, est_duration_secs, status, error, is_manual, edited_by, generated_at)
         VALUES (?, ?, ?, ?, ?, 'manual', ?, ?, 'ready', NULL, 1, ?, NOW())
         ON DUPLICATE KEY UPDATE headline = VALUES(headline), tts_text = VALUES(tts_text), source_hash = VALUES(source_hash), comment_count = VALUES(comment_count), model = 'manual',
           word_count = VALUES(word_count), est_duration_secs = VALUES(est_duration_secs), status = 'ready', error = NULL,
           is_manual = 1, edited_by = VALUES(edited_by), generated_at = NOW()`,
        [postId, headline, tts, contentHash(post, comments), comments.length, wordCount, estimateSeconds(tts), req.user.userId]);
      res.json({ ok: true, post_id: postId, headline, tts_text: tts, word_count: wordCount, est_duration_secs: estimateSeconds(tts), is_manual: true, model: 'manual' });
    } catch (error) {
      console.error('[radio] save segment error:', error);
      res.status(500).json({ error: 'Failed to save segment' });
    }
  });

  /**
   * POST /api/radio/posts/:postId/regenerate — admin (or the post author):
   * regenerate the segment for one post right now.
   */
  router.post('/posts/:postId/regenerate', async (req, res) => {
    try {
      const postId = parseInt(req.params.postId, 10);
      const [[post]] = await db.execute(
        `SELECT p.*, u.name AS author_name FROM posts p JOIN users u ON u.id = p.user_id WHERE p.id = ?`, [postId]);
      if (!post) return res.status(404).json({ error: 'Post not found' });
      if (req.user.role !== 'admin' && post.user_id !== req.user.userId) {
        return res.status(403).json({ error: 'Admin or author only' });
      }
      const [tagRows] = await db.execute(
        'SELECT t.name FROM post_tags pt JOIN tags t ON t.id = pt.tag_id WHERE pt.post_id = ?', [postId]);
      const comments = await loadComments(db, postId);
      const seg = await summarizePostForRadio(post, {
        authorName: post.author_name,
        companyName: companyName(),
        tags: tagRows.map(t => t.name),
        commentCount: comments.length,
        comments
      }, { strict: true });
      await db.execute(
        `INSERT INTO radio_segments (post_id, headline, tts_text, source_hash, comment_count, model, word_count, est_duration_secs, status, error, generated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'ready', NULL, NOW())
         ON DUPLICATE KEY UPDATE headline = VALUES(headline), tts_text = VALUES(tts_text), source_hash = VALUES(source_hash),
           comment_count = VALUES(comment_count),
           model = VALUES(model), word_count = VALUES(word_count), est_duration_secs = VALUES(est_duration_secs),
           status = 'ready', error = NULL, generated_at = NOW(), is_manual = 0, edited_by = NULL`,
        [postId, seg.headline, seg.tts_text, contentHash(post, comments), comments.length, seg.model, seg.word_count, seg.est_duration_secs]);
      res.json({ ok: true, post_id: postId, comment_count: comments.length, ...seg });
    } catch (error) {
      console.error('[radio] regenerate error:', error);
      res.status(500).json({ error: `Failed to regenerate: ${error.message}` });
    }
  });

  // requireAdmin is accepted for parity with other routers; admin-only ops live in the worker CLI.
  void requireAdmin;
  return router;
};
